var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var all=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t=>t.gameObject);return string.Join("\n",all.Where(g=>g.GetComponents<UnityEngine.Component>().Any(c=>c!=null&&c.GetType().FullName.Contains("VFX")||c!=null&&c.GetType().FullName.Contains("CameraShake")||c!=null&&c.GetType().FullName.Contains("DamageFlash"))).Select(g=>g.name+" => "+string.Join(",",g.GetComponents<UnityEngine.Component>().Where(c=>c!=null).Select(c=>c.GetType().FullName))));
